from pathlib import Path
import json
import numpy as np,pandas as pd
OUT=(Path(__import__('os').environ['CRRM_WORKSPACE']) / 'phase22_Result3_incremental_information_20261112')
read=lambda f:pd.read_csv(OUT/'tables'/f)
model=read('08_conditional_clinical_models.csv');nested=read('21_all_nested_models_Holm8_summary.csv');comp=read('17_measured_composition_models.csv');proxy=read('18_disjoint_expression_proxy_models.csv');direct=read('09_direct_branch_difference.csv');ab=read('07_LCN2_ablation_effects.csv');rec=read('14_paired_recovery_ablation.csv');infl=read('10_every_gene_omission_influence.csv');cov=read('06_score_eligibility.csv');oof=read('20_descriptive_out_of_fold_comparison.csv')
rows=[]
def row(r,adjusted=np.nan,family='None / descriptive'):
    return {'Study':r.dataset,'Target':r.target,'Model':r.model,'Cases':r.n,'Severe or inpatient':r.n_positive,'Mild or outpatient':r.n_reference,'Estimate':r.effect,'95% CI lower':r.CI95_low,'95% CI upper':r.CI95_high,'Model P':r.p_value,'Adjusted P':adjusted,'Correction family':family,'Role':r.role}
for _,r in model[model.role.eq('Strict severity')].iterrows():
    if r.target=='CRRM24' and r.model in nested.model.unique():
        if r.model=='Clinical+Zhang10+IFNUnion':q=r.strict_Holm2_P;family='Holm2 focal conditional tests'
        else:q=nested.loc[nested.dataset.eq(r.dataset)&nested.model.eq(r.model),'nested_Holm8_P'].iloc[0];family='Holm8 all nested models; additional reporting'
    else:q=r.strict_Holm2_P;family='Holm2 separate sensitivity family'
    rows.append(row(r,q,family))
for _,r in comp.iterrows():rows.append(row(r,r.composition_Holm2_P,'Holm2 after-composition tests' if 'after_' in r.model else 'Same-case baseline; descriptive'))
for _,r in proxy[proxy.role.eq('Strict severity')].iterrows():rows.append(row(r,r.strict_Holm2_P,'Holm2 expression-proxy sensitivity'))
for _,r in direct[direct.role.eq('Strict severity')].iterrows():rows.append(row(r,r.strict_Holm2_P,'Holm2 direct branch contrasts'))
for _,r in model[model.role.ne('Strict severity')&model.target.eq('CRRM24')&model.model.eq('Clinical+Zhang10+IFNUnion')].iterrows():rows.append(row(r))
A=pd.DataFrame(rows);assert len(A)==24;A.to_csv(OUT/'tables/S4A_Models.csv',index=False)
A['Target']=A.Target.replace({'CRRM24':'LCN2-omitted subset','CRRMDisjoint':'LCN2/IFN-disjoint subset','CRRM388':'Frozen total CRRM','CRRM24minusIFNUnion':'LCN2-omitted subset minus IFN'})
A['Model']=A.Model.replace({'Clinical':'Clinical factors','Clinical+Zhang10':'Clinical + published neutrophil panel','Clinical+IFNUnion':'Clinical + IFN reference','Clinical+Zhang10+IFNUnion':'Clinical + both references','Clinical+ZhangSeverityPair+IFNUnion':'Clinical + ARG1/PADI4 + IFN','Clinical+Zhang10+IFNUnion+MCP2':'Clinical + both references + disjoint lineage proxies','Measured_myeloid__Same_cases_before_composition':'Matched cases: both references','Measured_myeloid__Same_cases_after_composition':'Matched cases: both references + measured myeloid fractions','Measured_CLR3__Same_cases_before_composition':'Complete cases: both references','Measured_CLR3__Same_cases_after_composition':'Complete cases: both references + three composition PCs'})
A.to_csv(OUT/'tables/S4A_Models.csv',index=False)
B=[]
for _,r in ab[ab.role.eq('Strict severity')].iterrows():
    B.append({'Study':r.dataset,'Analysis':r.target+' Severe-minus-Mild','Cases or pairs':r.n_positive+r.n_reference,'Measured members':r.n_measured,'Estimate':r.effect,'Lower bound':r.CI95_low,'Upper bound':r.CI95_high,'Interval type':'Welch95%CI','Model P':r.p_value,'Adjusted P':r.ablation_Holm2_P,'Role':'LCN2ablation Holm2' if r.target=='CRRM24' else 'Contextual estimate'})
r=rec[rec.metric.eq('CRRM24')].iloc[0];ng=cov.loc[cov.dataset.eq('GSE69606')&cov.set_name.eq('CRRM24'),'n_measured'].iloc[0]
B.append({'Study':'GSE69606','Analysis':'LCN2omitted;Recovery-minus-Acute','Cases or pairs':15,'Measured members':ng,'Estimate':r.effect,'Lower bound':r.CI95_low,'Upper bound':r.CI95_high,'Interval type':'Pairedt95%CI','Model P':r.p_value,'Adjusted P':np.nan,'Role':f'Separate planned secondary;exactP={r.exact_signflip_P:.12g}'})
for ds in ['GSE246622','GSE69606']:
    d=infl[infl.dataset.eq(ds)&infl.model.eq('Clinical')];r=model[model.dataset.eq(ds)&model.target.eq('CRRM24')&model.model.eq('Clinical')].iloc[0];B.append({'Study':ds,'Analysis':'Every additional member omitted;clinical model','Cases or pairs':r.n,'Measured members':len(d),'Estimate':r.effect,'Lower bound':d.effect.min(),'Upper bound':d.effect.max(),'Interval type':'Min-max influence range;NOTaCI','Model P':np.nan,'Adjusted P':np.nan,'Role':'All omissions retained;no member selection'})
B=pd.DataFrame(B);assert len(B)==9;B.to_csv(OUT/'tables/S4B_Stability.csv',index=False)
B['Analysis']=B.Analysis.str.replace('CRRM25','Full annotation subset',regex=False).str.replace('CRRM24','LCN2-omitted subset',regex=False).str.replace('CRRMDisjoint','LCN2/IFN-disjoint subset',regex=False).str.replace('LCN2omitted;Recovery-minus-Acute','LCN2 omitted; recovery minus acute',regex=False)
B['Role']=B.Role.str.replace('LCN2ablation','LCN2 ablation',regex=False).str.replace('secondary;exactP=','secondary; exact P = ',regex=False);B['Interval type']=B['Interval type'].replace({'Welch95%CI':'Welch 95% CI','Pairedt95%CI':'Paired t 95% CI','Min-max influence range;NOTaCI':'Minimum–maximum influence range; not a CI'});B.to_csv(OUT/'tables/S4B_Stability.csv',index=False)
C=cov[cov.dataset.isin(['GSE246622','GSE69606','GSE105450'])&cov.set_name.ne('CRRM388')].copy();C['measured_fraction']=C.n_measured/C.n_nominal;C=C.rename(columns={'dataset':'Study','set_name':'Reference or subset','n_nominal':'Nominal members','n_measured':'Measured members','eligible':'Eligible','algorithm':'Score definition','measured_fraction':'Measured fraction'});C=C[['Study','Reference or subset','Nominal members','Measured members','Measured fraction','Eligible','Score definition']];assert len(C)==24;C.to_csv(OUT/'tables/S4C_Measurement.csv',index=False)
C['Eligible']=C['Eligible'].astype(str).str.lower().eq('true').map({True:'Yes',False:'No'});C.to_csv(OUT/'tables/S4C_Measurement.csv',index=False)
C['Score definition']=C['Reference or subset'].map({'CRRM25':'Equal-weight mean gene z score; full annotation','CRRM24':'Equal-weight mean gene z score; LCN2 omitted','CRRMDisjoint':'Equal-weight mean gene z score; LCN2/IFN omitted','Zhang10':'Mean gene z score constructed here from published ten-gene list','ZhangSeverityPair':'Mean gene z score constructed here from ARG1/PADI4','IFNUnion':'Mean gene z score of the exact Hallmark IFN union','MCPNeutrophils':'Native mean log expression of disjoint neutrophil markers','MCPMonocytic':'Native mean log expression of disjoint monocytic markers'})
C['Reference or subset']=C['Reference or subset'].replace({'CRRM25':'Full annotation subset','CRRM24':'LCN2-omitted subset','CRRMDisjoint':'LCN2/IFN-disjoint subset','Zhang10':'Published ten-gene panel','ZhangSeverityPair':'Published ARG1/PADI4 pair','IFNUnion':'Hallmark IFN union','MCPNeutrophils':'Disjoint neutrophil markers','MCPMonocytic':'Disjoint monocytic markers'});C.to_csv(OUT/'tables/S4C_Measurement.csv',index=False)
D=oof[['dataset','role','n','Baseline_logloss','Augmented_logloss','logloss_improvement','Baseline_Brier','Augmented_Brier','Brier_improvement']].rename(columns={'dataset':'Study','role':'Role','n':'Cases','Baseline_logloss':'Baseline log loss','Augmented_logloss':'Augmented log loss','logloss_improvement':'Log loss reduction','Baseline_Brier':'Baseline Brier','Augmented_Brier':'Augmented Brier','Brier_improvement':'Brier reduction'});D.to_csv(OUT/'tables/S4D_Heldout.csv',index=False)
spec=[
dict(sheet='S4A_Models',file='S4A_Models.csv',title='Table S4A. Conditional severity associations and measured-cell sensitivity models',notes=['All analyses are exploratory after the initial Result3. CRRM24 denotes the nominal frozen25subset minusLCN2;it is not a newly selected signature. Clinical factors:age spline3df andsex inGSE246622;no individual covariates available inGSE69606.','Zhang10 is an equal-weight mean-z comparator made here from the published10hubgenes,not the original fittedclassifier. IFNUnion is the exact224-symbol HallmarkIFN-alpha/gamma union,restricted to measurable unique mappings.','Model P usesHC3SE andresidual-df t inference. The focal2-cohort Holm family is retained. ConservativeHolm8 acrossall4nestedmodels x2cohorts is additional reporting after modelcalculation;no tests replaced.','Measured-myeloid models compare identical33cases before/after arcsine-square-root frequencies ofauthorclusters113+114 and221. CLR3 models compare identical24completecases before/after3PCs from all256measuredfractions. The two after-composition tests shareHolm2.','Hospitalization andRMA rows are endpoint/source sensitivities. Neither supplies another strict-severity study. All confidence intervals are pointwise.']),
dict(sheet='S4B_Stability',file='S4B_Stability.csv',title='Table S4B. Member-omission stability and paired recovery',notes=['Full25anddisjointsubset rows are contextual unadjusted effects. The twoLCN2-omitted severity tests useHolm2. RecoveryLCN2ablation is a separate secondary paired test;the exact32768sign-flip P is retained inRole.','Member-omission bounds are the minimum andmaximum coefficients across every additional measured-gene omission afterLCN2removal.They are influence ranges,not confidence intervals or independentreplications.']),
dict(sheet='S4C_Measurement',file='S4C_Measurement.csv',title='Table S4C. Frozen subset and comparator measurement coverage',notes=['Nominal CRRM25/24/Disjoint memberships are25/24/21. IFNUnion contains224rawsymbols;198resolve uniquely in the frozen annotation,196are measured in each source.','PADI4andELANE were resolved before new scoring using officialGRCh38primary Ensemblrecords. Only exact single-symbol,complete,nonconflictingprobes were rehabilitated;no388member ormeasurementchanged.','MCP markers were taken fromcommitb6eac73e91c246fcff0bb1a5c68a816cd588fc48,andgenesoverlappingCRRM388,IFNUnion,orZhang10were removed. Scores are disjoint native-log markerproxies,not measuredcellfractions.']),
dict(sheet='S4D_Heldout',file='S4D_Heldout.csv',title='Table S4D. Descriptive leave-one-unit-out comparison of reference and augmented models',notes=['Baseline:clinicalcovariates+Zhang10+IFNUnion.Augmented:the same model plusLCN2-omittedCRRMsubset.Fixed ridge-logistic objective uses summednegative loglikelihood+0.5sum(noninterceptcoefficient^2);lambda1was not tuned.','Each held-out profile is excluded fromgene-reference means/SD;model-variable scaling is fitted ontrainingcasesonly. The inheritedclinical spline basis is fixed. Each patient contributes one held-out probabilitypermodel.','Positive loss reductions favor augmentation;negative values favor baseline.The performance comparison is descriptive,without inferential P orCI,anddoesnot constitute prospectiveprediction validation.RMA repeats the mainstudy.'])]
spec[0]['notes']=[
'All analyses are exploratory after the initial Result3. The LCN2-omitted subset is the frozen 25-member annotation with LCN2 excluded; it is not a replacement signature. Clinical factors are the frozen age spline and sex in GSE246622; individual covariates were unavailable in GSE69606.',
'The published-panel comparator is an equal-weight mean z score constructed here from ten reported hub genes, not the original fitted classifier. IFN uses the exact 224-symbol Hallmark union with measurable unique mappings.',
'Model P uses HC3 standard errors and residual-df t inference. Focal conditional tests retain Holm correction across two strict studies. An additional conservative Holm summary covers all eight nested models; no original tests were replaced.',
'Measured-myeloid models compare the same 33 cases before and after adding transformed frequencies of author clusters 113+114 and 221. Complete-composition models compare the same 24 cases before and after adding three CLR PCs from all 256 measured clusters. The two composition-adjusted tests share Holm correction.',
'Hospitalization and RMA rows are endpoint and source sensitivities; neither adds another strict-severity study. Confidence intervals are pointwise.']
spec[1]['notes']=[
'Full and disjoint subset rows are contextual unadjusted effects. The two LCN2-omission severity tests use Holm correction. Recovery omission is a separate secondary paired test; its exact 32,768-sign-flip P is retained in the Role field.',
'Member-omission bounds are the minimum and maximum coefficients across every additional measured-member omission after LCN2 removal. These are influence ranges, not confidence intervals or independent replications.']
spec[2]['notes']=[
'Nominal full, LCN2-omitted, and disjoint memberships are 25, 24, and 21. The IFN union contains 224 raw symbols; 198 resolve uniquely and 196 are measured per source.',
'PADI4 and ELANE were resolved before new scoring using official GRCh38 primary Ensembl records. Only exact single-symbol, complete, nonconflicting probes were rehabilitated. No CRRM388 member or measurement changed.',
'MCP-counter markers are pinned to commit b6eac73e91c246fcff0bb1a5c68a816cd588fc48. All overlaps with CRRM388, IFN, and the published panel were removed. These native mean-log marker scores are expression proxies, not measured fractions.']
spec[3]['notes']=[
'Baseline includes clinical covariates, the published neutrophil panel, and IFN. The augmented model adds the LCN2-omitted subset. The fixed ridge-logistic objective is summed negative log likelihood plus one-half the squared nonintercept coefficients; lambda = 1 was not tuned.',
'Each held-out profile is excluded from gene-reference means and SD. Model-variable scaling uses training cases only; the inherited clinical spline basis is fixed. Each patient has one held-out probability per model.',
'Positive loss reductions favor augmentation; negative values favor baseline. Performance is descriptive, without inferential P values or confidence intervals, and does not constitute prospective prediction validation. RMA repeats the main study.']
(OUT/'parameters/workbook_spec.json').write_text(json.dumps(spec,ensure_ascii=False,indent=2)+'\n')
